def p(text,style='BodyProject'):return Paragraph(html.escape(str(text)).replace(chr(10),"<br/>"),styles[style])
def table(headers,rows,widths=None):
    t=Table([[p(v,'TableProject') for v in headers]]+[[p(v,'TableProject') for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4f0f1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor('#176b75')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#dbe2e8')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t
def image(name,width=465):
    from PIL import Image as PIL
    f=F/(name+'.png');w,h=PIL.open(f).size;return Image(str(f),width=width,height=width*h/w)
